class Solution {
    public String entityParser(String text){
        String[] entities={
            "&quot;","&apos;","&amp;","&gt;","&lt;","&frasl;"
        },values={
            "\"","'","&",">","<","/"
        };
        StringBuilder answer=new StringBuilder();
        for(int i=0;i<text.length();){
            boolean matched=false;
            if(text.charAt(i)=='&')for(int j=0;j<entities.length;j++)if(text.startsWith(entities[j],i)){
                answer.append(values[j]);
                i+=entities[j].length();
                matched=true;
                break;
            }
            if(!matched)answer.append(text.charAt(i++));
        }
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun entityParser(text:String):String{
        val entities=listOf("&quot;" to "\"","&apos;" to "'","&amp;" to "&","&gt;" to ">","&lt;" to "<","&frasl;" to "/");
        val answer=StringBuilder();
        var i=0;
        while(i<text.length){
            val match=if(text[i]=='&')entities.firstOrNull{
                text.startsWith(it.first,i)
            }else null;
            if(match==null)answer.append(text[i++])else{
                answer.append(match.second);
                i+=match.first.length
            }
        };
        return answer.toString()
    }
}

